import { EventEmitter } from "node:events";
import type { FastifyBaseLogger } from "fastify";
import puppeteer, { type Browser } from "puppeteer-core";
import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";

import type { BrowserLauncherOptions } from "../../types/browser.js";
import { getExtensionPaths } from "../../utils/extensions.js";
import { CDPService } from "./cdp.service.js";
import { LaunchTimeoutError, ResourceError } from "./errors/launch-errors.js";
import { BasePlugin, ShutdownReason } from "./plugins/core/base-plugin.js";
import { ProfileInUseError, releaseStaleProfileLock } from "./utils/profile-lock.js";
import type { CommandEngine } from "../commands/engine.js";
import { CommandsPlugin } from "../commands/plugin.js";

vi.mock("puppeteer-core", async (importOriginal) => {
  const actual = await importOriginal<typeof import("puppeteer-core")>();
  return { ...actual, default: { launch: vi.fn() } };
});

vi.mock("../file.service.js", () => ({
  FileService: {
    getInstance: () => ({
      cleanupFiles: vi.fn().mockResolvedValue(undefined),
      getBaseFilesPath: () => "/fixture/downloads",
    }),
  },
}));

vi.mock("../timezone-fetcher.service.js", () => ({
  TimezoneFetcher: class {
    getTimezone() {
      return Promise.resolve("UTC");
    }
  },
}));

vi.mock("../../utils/extensions.js", () => ({
  getExtensionPaths: vi.fn().mockResolvedValue([]),
}));

vi.mock("./instrumentation/target-manager.js", () => ({
  TargetInstrumentationManager: class {
    attach = vi.fn().mockResolvedValue(undefined);
    detach = vi.fn();
  },
}));

vi.mock("./utils/profile-lock.js", async (importOriginal) => ({
  ...(await importOriginal<typeof import("./utils/profile-lock.js")>()),
  releaseStaleProfileLock: vi.fn(async () => ({ status: "free" })),
}));

const logger = {
  child: () => logger,
  debug: vi.fn(),
  error: vi.fn(),
  info: vi.fn(),
  warn: vi.fn(),
};

function sessionConfig(id: string, fixtureTag: string): BrowserLauncherOptions {
  return {
    options: { headless: false },
    userDataDir: "/fixture/browser-data",
    userAgent: "FixtureBrowser/1.0",
    skipFingerprintInjection: true,
    extra: { session: { id }, fixtureTag },
  };
}

function fakeBrowser(): Browser {
  const cdp = { send: vi.fn().mockResolvedValue({}), detach: vi.fn().mockResolvedValue(undefined) };
  const target = {
    type: () => "browser",
    createCDPSession: vi.fn().mockResolvedValue(cdp),
  };
  const page = {
    target: () => target,
    close: vi.fn().mockResolvedValue(undefined),
    isClosed: () => false,
  };
  return Object.assign(new EventEmitter(), {
    close: vi.fn().mockResolvedValue(undefined),
    process: () => ({ kill: vi.fn() }),
    pages: vi.fn().mockResolvedValue([page]),
    newPage: vi.fn().mockResolvedValue(page),
    target: () => target,
    targets: () => [],
    wsEndpoint: () => "ws://fixture/browser",
  }) as unknown as Browser;
}

function lifecycleFixture() {
  const service = new CDPService({}, logger as unknown as FastifyBaseLogger);
  vi.spyOn(service, "getBrowserState").mockResolvedValue({});
  const events: Array<{
    phase: "launch" | "shutdown";
    config: BrowserLauncherOptions | null;
  }> = [];

  // Hook metadata is opaque to CDPService. Exercise the real lifecycle with
  // a mocked browser, without modelling any particular hook implementation.
  service.registerLaunchHook((config) => {
    events.push({ phase: "launch", config });
  });
  service.registerShutdownHook((config) => {
    events.push({ phase: "shutdown", config });
  });

  return { service, events };
}

describe("CDPService lifecycle hook ownership", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.mocked(puppeteer.launch).mockImplementation(async () => fakeBrowser());
    vi.mocked(getExtensionPaths).mockResolvedValue([]);
  });

  afterEach(() => {
    vi.clearAllTimers();
    vi.useRealTimers();
    vi.restoreAllMocks();
    vi.clearAllMocks();
  });

  test("tears down the idle browser before running incoming launch hooks", async () => {
    const { service, events } = lifecycleFixture();
    await service.launch();
    const idleConfig = service.getLaunchConfig();
    const incoming = sessionConfig("incoming", "incoming-metadata");
    events.length = 0;

    await service.startNewSession(incoming);

    expect(events.map((event) => event.phase)).toEqual(["shutdown", "launch"]);
    expect(events[0].config?.extra).toEqual(idleConfig?.extra);
    expect(events[1].config).toBe(incoming);
    await service.shutdown(ShutdownReason.SESSION_END);
  });

  test("passes outgoing metadata to shutdown hooks during relaunch", async () => {
    const { service, events } = lifecycleFixture();
    const outgoing = sessionConfig("outgoing", "outgoing-metadata");
    const incoming = sessionConfig("incoming", "incoming-metadata");
    await service.startNewSession(outgoing);
    events.length = 0;

    await service.startNewSession(incoming);

    expect(events.map((event) => event.phase)).toEqual(["shutdown", "launch"]);
    expect(events[0].config?.extra).toBe(outgoing.extra);
    expect(events[1].config).toBe(incoming);
    await service.shutdown(ShutdownReason.SESSION_END);
    expect(events.at(-1)?.config?.extra).toBe(incoming.extra);
  });

  test("updates shutdown ownership when reusing the browser", async () => {
    const { service, events } = lifecycleFixture();
    await service.startNewSession(sessionConfig("first", "shared-metadata"));
    const browser = service.getBrowserInstance();
    const second = sessionConfig("second", "shared-metadata");
    events.length = 0;

    await service.startNewSession(second);

    expect(service.getBrowserInstance()).toBe(browser);
    expect(puppeteer.launch).toHaveBeenCalledOnce();
    expect(events).toEqual([]);
    await service.shutdown(ShutdownReason.SESSION_END);
    expect(events).toEqual([{ phase: "shutdown", config: second }]);
    expect(events[0].config).toBe(second);
  });

  test("reuses the browser when the primary page is already closed", async () => {
    const { service } = lifecycleFixture();
    await service.startNewSession(sessionConfig("first", "shared-metadata"));
    const closed = {
      isClosed: () => true,
      close: vi.fn().mockRejectedValue(new Error("Protocol error: Connection closed.")),
    };
    Object.assign(service as unknown as Record<string, unknown>, { primaryPage: closed });

    await service.startNewSession(sessionConfig("second", "shared-metadata"));

    expect(closed.close).not.toHaveBeenCalled();
    expect(await service.getPrimaryPage()).not.toBe(closed);
    await service.shutdown(ShutdownReason.SESSION_END);
  });

  test("leaves no rejection behind when a page closes during setup", async () => {
    const { service } = lifecycleFixture();
    await service.startNewSession({
      ...sessionConfig("first", "first-metadata"),
      options: { headless: true },
    });
    let closed = false;
    const page = {
      isClosed: () => closed,
      url: () => "about:blank",
      on: vi.fn(),
      evaluateOnNewDocument: vi.fn(async () => {
        closed = true;
        throw new Error("Protocol error (Page.addScriptToEvaluateOnNewDocument): Target closed");
      }),
    };
    const target = { _targetId: "closing", type: () => "page", page: async () => page };

    await (
      service as unknown as { handleNewTarget: (target: unknown) => Promise<void> }
    ).handleNewTarget(target);
    await vi.advanceTimersByTimeAsync(0);

    expect(page.evaluateOnNewDocument).toHaveBeenCalledOnce();
    await service.shutdown(ShutdownReason.SESSION_END);
  });

  test("retains hook ownership across session end and the next idle-browser relaunch", async () => {
    const { service, events } = lifecycleFixture();
    const first = sessionConfig("first", "first-metadata");
    const second = sessionConfig("second", "second-metadata");
    await service.startNewSession(first);
    events.length = 0;

    await service.endSession();

    expect(events.map((event) => event.phase)).toEqual(["shutdown", "launch"]);
    expect(events[0].config?.extra).toBe(first.extra);
    expect(events[1].config?.extra).toBeUndefined();
    events.length = 0;

    await service.startNewSession(second);

    expect(events.map((event) => event.phase)).toEqual(["shutdown", "launch"]);
    expect(events[0].config?.extra).toBeUndefined();
    expect(events[1].config).toBe(second);
    await service.shutdown(ShutdownReason.SESSION_END);
  });

  test("does not pass incoming metadata to cleanup when a launch hook fails", async () => {
    const { service, events } = lifecycleFixture();
    await service.launch();
    const incoming = sessionConfig("incoming", "incoming-metadata");
    events.length = 0;
    service.registerLaunchHook(() => {
      throw new Error("Fixture launch hook failed");
    });
    const launch = service.launch.bind(service);
    vi.spyOn(service, "launch").mockImplementation((config) => launch(config, { maxAttempts: 1 }));

    await expect(service.startNewSession(incoming)).rejects.toThrow("Fixture launch hook failed");

    expect(events.map((event) => event.phase)).toEqual(["shutdown", "launch", "shutdown"]);
    expect(events[0].config?.extra).toBeUndefined();
    expect(events[1].config).toBe(incoming);
    expect(events[2].config).toBeNull();
  });

  function commandEngineCalls() {
    const browsers: Browser[] = [];
    vi.mocked(puppeteer.launch).mockImplementation(async () => {
      const browser = fakeBrowser();
      browsers.push(browser);
      return browser;
    });
    const { service } = lifecycleFixture();
    const calls: string[] = [];
    const engine = {
      prepare: (id: string) => calls.push(`prepare ${id}`),
      browserLaunched: (browser: Browser) => calls.push(`launched ${browsers.indexOf(browser)}`),
      browserReady: () => calls.push("ready"),
      browserClosed: (browser: Browser) => calls.push(`closed ${browsers.indexOf(browser)}`),
      sessionEnded: () => calls.push("ended"),
    };
    const session = { id: "first" };
    service.registerPlugin(
      new CommandsPlugin(engine as unknown as CommandEngine, { id: () => session.id }),
    );
    return { service, browsers, calls, session };
  }

  test("ends the command session before the browser closes", async () => {
    const { service, calls, session } = commandEngineCalls();

    await service.launch();
    await service.startNewSession(sessionConfig("first", "first-metadata"));
    await service.endSession(ShutdownReason.SECURITY_VIOLATION);
    session.id = "second";
    await service.startNewSession(sessionConfig("second", "second-metadata"));
    await service.endSession();

    expect(calls).toEqual([
      "launched 0",
      "ready",
      "prepare first",
      "closed 0",
      "launched 1",
      "ready",
      "ended",
      "closed 1",
      "launched 2",
      "ready",
      "prepare second",
      "closed 2",
      "launched 3",
      "ready",
      "ended",
      "closed 3",
      "launched 4",
      "ready",
    ]);
    await service.shutdown(ShutdownReason.SESSION_END);
  });

  test("ends the command session when the browser crashes", async () => {
    const { service, browsers, calls } = commandEngineCalls();

    await service.launch();
    await service.startNewSession(sessionConfig("first", "first-metadata"));
    (browsers[1] as unknown as EventEmitter).emit("disconnected");
    await vi.waitFor(() => expect(calls).toContain("launched 2"));

    expect(calls.slice(0, 9)).toEqual([
      "launched 0",
      "ready",
      "prepare first",
      "closed 0",
      "launched 1",
      "ready",
      "ended",
      "closed 1",
      "launched 2",
    ]);
    await service.shutdown(ShutdownReason.SESSION_END);
  });
});

describe("CDPService profile lock", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.mocked(puppeteer.launch).mockImplementation(async () => fakeBrowser());
    vi.mocked(getExtensionPaths).mockResolvedValue([]);
  });

  afterEach(() => {
    vi.clearAllTimers();
    vi.useRealTimers();
    vi.restoreAllMocks();
    vi.clearAllMocks();
  });

  test("releases a stale lock before each launch and names its own Chrome", async () => {
    const { service } = lifecycleFixture();
    const first = Object.assign(fakeBrowser(), {
      process: () => ({ pid: 4321, kill: vi.fn() }),
    }) as unknown as Browser;
    vi.mocked(puppeteer.launch).mockResolvedValueOnce(first);

    await service.startNewSession(sessionConfig("first", "first-metadata"));
    await service.startNewSession(sessionConfig("second", "second-metadata"));

    expect(vi.mocked(releaseStaleProfileLock).mock.calls).toEqual([
      ["/fixture/browser-data", undefined],
      ["/fixture/browser-data", 4321],
    ]);
    await service.shutdown(ShutdownReason.SESSION_END);
  });

  test("fails without retrying when another process owns the profile", async () => {
    const { service } = lifecycleFixture();
    vi.mocked(releaseStaleProfileLock).mockRejectedValueOnce(
      new ProfileInUseError("/fixture/browser-data", 4105, 3210),
    );

    const attempt = service.launch(sessionConfig("blocked", "blocked-metadata"));

    await expect(attempt).rejects.toBeInstanceOf(ResourceError);
    await expect(attempt).rejects.toThrow(/in use by PID 4105 \(parent 3210\)/);
    expect(releaseStaleProfileLock).toHaveBeenCalledOnce();
    expect(puppeteer.launch).not.toHaveBeenCalled();
  });
});

describe("CDPService overlapping launches", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.mocked(puppeteer.launch).mockImplementation(async () => fakeBrowser());
    vi.mocked(getExtensionPaths).mockResolvedValue([]);
  });

  afterEach(() => {
    vi.clearAllTimers();
    vi.useRealTimers();
    vi.restoreAllMocks();
    vi.clearAllMocks();
  });

  test("starts a launch only after the previous launch has finished", async () => {
    const { service } = lifecycleFixture();
    const order: string[] = [];
    let launches = 0;
    vi.mocked(puppeteer.launch).mockImplementation(async () => {
      const id = ++launches;
      order.push(`launch ${id}`);
      if (id === 1) {
        await new Promise((resolve) => setTimeout(resolve, 1_000));
      }
      const browser = fakeBrowser();
      vi.mocked(browser.close).mockImplementation(async () => {
        order.push(`close ${id}`);
      });
      order.push(`ready ${id}`);
      return browser;
    });

    const idle = service.launch(sessionConfig("idle", "idle-metadata"));
    await vi.waitFor(() => expect(order).toEqual(["launch 1"]));
    const session = service.startNewSession(sessionConfig("session", "session-metadata"));
    await vi.advanceTimersByTimeAsync(1_000);
    const [, browser] = await Promise.all([idle, session]);

    expect(order).toEqual(["launch 1", "ready 1", "close 1", "launch 2", "ready 2"]);
    expect(service.getBrowserInstance()).toBe(browser);
    await service.shutdown(ShutdownReason.SESSION_END);
  });

  test("closes a browser that starts after its launch attempt timed out", async () => {
    const { service } = lifecycleFixture();
    const late = fakeBrowser();
    vi.mocked(puppeteer.launch).mockImplementationOnce(async () => {
      await new Promise((resolve) => setTimeout(resolve, 61_000));
      return late;
    });

    const timedOut = expect(
      service.launch(sessionConfig("first", "first-metadata")),
    ).rejects.toThrow(LaunchTimeoutError);
    await vi.advanceTimersByTimeAsync(60_000);
    await timedOut;
    const current = await service.launch(sessionConfig("second", "second-metadata"));
    await vi.advanceTimersByTimeAsync(1_000);

    expect(late.close).toHaveBeenCalledOnce();
    expect(service.getBrowserInstance()).toBe(current);
    await service.shutdown(ShutdownReason.SESSION_END);
  });

  test("does not launch a browser once its launch attempt timed out", async () => {
    const { service } = lifecycleFixture();
    let stalled = false;
    service.registerLaunchHook(async () => {
      if (!stalled) {
        stalled = true;
        await new Promise((resolve) => setTimeout(resolve, 61_000));
      }
    });

    const timedOut = expect(
      service.launch(sessionConfig("first", "first-metadata")),
    ).rejects.toThrow(LaunchTimeoutError);
    await vi.advanceTimersByTimeAsync(60_000);
    await timedOut;
    const current = await service.launch(sessionConfig("second", "second-metadata"));
    await vi.advanceTimersByTimeAsync(1_000);

    expect(puppeteer.launch).toHaveBeenCalledOnce();
    expect(service.getBrowserInstance()).toBe(current);
    await service.shutdown(ShutdownReason.SESSION_END);
  });
});

describe("CDPService downloads", () => {
  beforeEach(() => {
    vi.mocked(getExtensionPaths).mockResolvedValue([]);
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.clearAllMocks();
  });

  test("keeps the session that set the download folder open", async () => {
    const browser = fakeBrowser();
    vi.mocked(puppeteer.launch).mockImplementation(async () => browser);
    const service = new CDPService({}, logger as unknown as FastifyBaseLogger);
    await service.launch();
    const session = await browser.target().createCDPSession();
    expect(session.send).toHaveBeenCalledWith(
      "Browser.setDownloadBehavior",
      expect.objectContaining({ behavior: "allow", eventsEnabled: true }),
    );
    expect(session.detach).not.toHaveBeenCalled();
    await service.shutdown(ShutdownReason.SESSION_END);
  });
});

describe("CDPService cookies", () => {
  test("reads the default context cookies from the browser, not from a page", async () => {
    const service = new CDPService({}, logger as unknown as FastifyBaseLogger);
    const browser = {
      send: vi.fn().mockResolvedValue({ cookies: [{ name: "own" }] }),
      detach: vi.fn().mockResolvedValue(undefined),
    };
    const foreign = { send: vi.fn().mockResolvedValue({ cookies: [{ name: "foreign" }] }) };
    const main = {};
    Object.assign(service as unknown as Record<string, unknown>, {
      primaryPage: { isClosed: () => true },
      browserInstance: {
        defaultBrowserContext: () => main,
        target: () => ({ createCDPSession: async () => browser }),
        targets: () => [
          { type: () => "page", browserContext: () => main, _session: () => foreign },
        ],
      },
    });
    expect(await service.getCookies()).toEqual([{ name: "own" }]);
    expect(browser.send).toHaveBeenCalledWith("Storage.getCookies");
    expect(browser.detach).toHaveBeenCalled();
    expect(foreign.send).not.toHaveBeenCalled();
  });
});

import { describe, expect, test, vi } from "vitest";

import { CDPService } from "./cdp.service.js";

const logger = {
  child: () => logger,
  debug: vi.fn(),
  error: vi.fn(),
  info: vi.fn(),
  warn: vi.fn(),
};

const MOBILE_UA =
  "Mozilla/5.0 (Linux; Android 16; HON-AN00) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Mobile Safari/537.36";
const DESKTOP_UA =
  "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36";

function fakePage() {
  const send = vi.fn().mockResolvedValue({});
  const detach = vi.fn().mockResolvedValue(undefined);
  const page = {
    createCDPSession: vi.fn().mockResolvedValue({ send, detach }),
    setUserAgent: vi.fn().mockResolvedValue(undefined),
    setExtraHTTPHeaders: vi.fn().mockResolvedValue(undefined),
    evaluateOnNewDocument: vi.fn().mockResolvedValue(undefined),
    isClosed: vi.fn().mockReturnValue(false),
  };
  return { page, send, detach };
}

function serviceWith(fingerprintData: unknown) {
  const service = new CDPService({}, logger as any);
  Object.assign(service as any, {
    fingerprintData,
    currentSessionConfig: {},
    launchConfig: { userAgent: (fingerprintData as any).fingerprint.navigator.userAgent },
  });
  return service;
}

const mobileFingerprint = {
  fingerprint: {
    navigator: {
      userAgent: MOBILE_UA,
      platform: "Linux armv8l",
      maxTouchPoints: 10,
      userAgentData: {
        brands: [{ brand: "Chromium", version: "155" }],
        fullVersionList: [{ brand: "Chromium", version: "155.0.8059.79" }],
        uaFullVersion: "155.0.8059.79",
        platform: "Android",
        platformVersion: "16.0.0",
        architecture: "",
        bitness: "",
        model: "HON-AN00",
        mobile: true,
      },
    },
    screen: { width: 508, height: 1074, innerWidth: 500, innerHeight: 983, devicePixelRatio: 3 },
  },
  headers: { "accept-language": "es-MX,es;q=0.9", "sec-ch-ua-mobile": "?1" },
};

const desktopFingerprint = {
  fingerprint: {
    navigator: {
      userAgent: DESKTOP_UA,
      platform: "Linux x86_64",
      maxTouchPoints: 0,
      userAgentData: {
        brands: [{ brand: "Chromium", version: "155" }],
        uaFullVersion: "155.0.8059.79",
        platform: "Linux",
        mobile: false,
      },
    },
    screen: { width: 1920, height: 1080, devicePixelRatio: 1 },
  },
  headers: { "accept-language": "en-US,en;q=0.9" },
};

describe("CDPService mobile device emulation", () => {
  test("fits the layout viewport inside the window and enables matching touch input", async () => {
    const service = serviceWith(mobileFingerprint);
    const { page, send, detach } = fakePage();

    await (service as any).applyDeviceMetricsOverride(page);

    expect(send).toHaveBeenNthCalledWith(1, "Page.setDeviceMetricsOverride", {
      screenWidth: 508,
      screenHeight: 1074,
      width: 500,
      height: 983,
      mobile: true,
      screenOrientation: { angle: 0, type: "portraitPrimary" },
      deviceScaleFactor: 3,
    });
    expect(send).toHaveBeenNthCalledWith(2, "Emulation.setTouchEmulationEnabled", {
      enabled: true,
      maxTouchPoints: 10,
    });
    expect(detach).not.toHaveBeenCalled();
  });

  test("keeps one session attached for the page's metrics and user agent overrides", async () => {
    const service = serviceWith(mobileFingerprint);
    const { page, send, detach } = fakePage();

    await (service as any).applyDeviceMetricsOverride(page);
    await (service as any).injectFingerprintSafely(page, mobileFingerprint);

    expect(page.createCDPSession).toHaveBeenCalledOnce();
    expect(detach).not.toHaveBeenCalled();
    expect(send).toHaveBeenCalledWith(
      "Emulation.setUserAgentOverride",
      expect.objectContaining({ userAgent: MOBILE_UA }),
    );
  });

  test("sends coherent Android metadata and keeps navigator.platform separate", async () => {
    const service = serviceWith(mobileFingerprint);
    const { page, send } = fakePage();

    await (service as any).injectFingerprintSafely(page, mobileFingerprint);

    const metadata = {
      brands: [{ brand: "Chromium", version: "155" }],
      fullVersionList: [{ brand: "Chromium", version: "155.0.8059.79" }],
      fullVersion: "155.0.8059.79",
      platform: "Android",
      platformVersion: "16.0.0",
      architecture: "",
      model: "HON-AN00",
      mobile: true,
      bitness: "",
      wow64: false,
      formFactors: ["Mobile"],
    };
    expect(page.setUserAgent).toHaveBeenCalledWith(MOBILE_UA, metadata);
    expect(send).toHaveBeenCalledWith("Emulation.setUserAgentOverride", {
      userAgent: MOBILE_UA,
      acceptLanguage: "es-MX,es",
      platform: "Linux armv8l",
      userAgentMetadata: metadata,
    });

    const script = page.evaluateOnNewDocument.mock.calls[0][0] as string;
    expect(script).toContain('const FIXED_PLATFORM = "Linux armv8l"');
    expect(script).toContain('const FIXED_UA_PLATFORM = "Android"');
    expect(script).toContain("const FIXED_MOBILE = true");
    expect(script).toContain('const FIXED_ARCHITECTURE = ""');
    expect(script).toContain('const FIXED_MODEL = "HON-AN00"');
    expect(script).toContain('const FIXED_PLATFORM_VERSION = "16.0.0"');
  });

  test("takes the form factor from the fingerprint, so an Android tablet reports Desktop", async () => {
    const tablet = structuredClone(mobileFingerprint);
    tablet.fingerprint.navigator.userAgent =
      "Mozilla/5.0 (Linux; Android 14; SM-X710) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36";
    tablet.fingerprint.navigator.userAgentData.mobile = false;
    tablet.fingerprint.navigator.userAgentData.model = "SM-X710";
    const service = serviceWith(tablet);
    const { page, send } = fakePage();

    await (service as any).applyDeviceMetricsOverride(page);
    await (service as any).injectFingerprintSafely(page, tablet);

    expect(send).toHaveBeenCalledWith(
      "Page.setDeviceMetricsOverride",
      expect.objectContaining({ mobile: true }),
    );
    expect(send).toHaveBeenCalledWith("Emulation.setTouchEmulationEnabled", {
      enabled: true,
      maxTouchPoints: 10,
    });
    expect(send).toHaveBeenCalledWith(
      "Emulation.setUserAgentOverride",
      expect.objectContaining({
        userAgentMetadata: expect.objectContaining({ mobile: false, formFactors: ["Desktop"] }),
