describe("CDPService without request interception", () => {
  let dataDir: string;
  let server: http.Server;
  let origin: string;
  let service: CDPService | undefined;
  let client: Browser | undefined;

  beforeAll(async () => {
    dataDir = fs.mkdtempSync(path.join(os.tmpdir(), "steel-interception-"));
    server = http.createServer((req, res) => {
      if (req.url === "/app.js") {
        res.writeHead(200, { "content-type": "application/javascript" });
        res.end(
          `window.external_ = [localStorage.getItem("token"), sessionStorage.getItem("tab")];`,
        );
        return;
      }
      res.writeHead(200, { "content-type": "text/html" });
      res.end(
        `<script>window.inline_ = [localStorage.getItem("token"), sessionStorage.getItem("tab")];</script><script src="/app.js"></script>`,
      );
    });
    await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
    origin = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  });

  afterEach(async () => {
    vi.restoreAllMocks();
    await client?.disconnect().catch(() => {});
    await service?.shutdown(ShutdownReason.SESSION_END).catch(() => {});
    client = undefined;
    service = undefined;
  });

  afterAll(async () => {
    await new Promise((resolve) => server.close(resolve));
    fs.rmSync(dataDir, { recursive: true, force: true });
  });

  async function start(config: Partial<BrowserLauncherOptions> = {}) {
    service = new CDPService({}, logger as unknown as FastifyBaseLogger, undefined, false);
    await service.startNewSession({
      options: {
        headless: true,
        args: ["--no-sandbox", "--remote-debugging-address=127.0.0.1", "--remote-debugging-port=0"],
      },
      skipFingerprintInjection: true,
      userDataDir: fs.mkdtempSync(path.join(dataDir, "profile-")),
      ...config,
    });
    client = await puppeteer.connect({
      browserWSEndpoint: service.getBrowserInstance()!.wsEndpoint(),
      defaultViewport: null,
    });
    const [page] = await client.pages();
    return page;
  }

  test("blocks file:// navigations before the file loads", async () => {
    const secret = [REDACTED], "secret.txt");
    fs.writeFileSync(secret, "file-guard-secret");
    const page = await start();
    const endSession = vi.spyOn(service!, "endSession").mockResolvedValue(undefined);
    const session = await page.createCDPSession();

    session.send("Page.navigate", { url: `file://${secret}` }).catch(() => {});
    const seen: string[] = [];
    const deadline = Date.now() + 1500;
    while (Date.now() < deadline) {
      const result = await session
        .send("Runtime.evaluate", {
          expression: "document.documentElement ? document.documentElement.innerText : ''",
          returnByValue: true,
        })
        .catch(() => undefined);
      seen.push(String(result?.result.value ?? ""));
    }

    expect(seen.join("\n")).not.toContain("file-guard-secret");
    expect(endSession).toHaveBeenCalledWith(ShutdownReason.SECURITY_VIOLATION);
  }, 30000);

  test("restores session storage before the page's first script runs", async () => {
    const page = await start({
      sessionContext: {
        localStorage: { [origin]: { token: "[REDACTED]" } },
        sessionStorage: { [origin]: { tab: "session-tab" } },
      },
    });

    await page.goto(origin);

    expect(await page.evaluate(() => [(window as any).inline_, (window as any).external_])).toEqual(
      [
        ["session-token", "session-tab"],
        ["session-token", "session-tab"],
      ],
    );
  }, 30000);
});

import { describe, expect, test } from "vitest";
import { hideSecrets, SECRET_MASK, secretMask } from "./secrets.js";

function slowHide(text: string, secrets: string[], minimum: number): string {
  const ends = new Array<number>(text.length).fill(0);
  for (const secret of secrets) {
    for (const variant of [secret, secret.replace(/\s+/g, " ").trim()]) {
      if (variant.length < minimum) {
        continue;
      }
      for (let at = text.indexOf(variant); at >= 0; at = text.indexOf(variant, at + 1)) {
        ends[at] = Math.max(ends[at], at + variant.length);
      }
    }
  }
  let hidden = "";
  let until = 0;
  ends.forEach((end, index) => {
    if (end === 0) {
      return;
    }
    if (index >= until) {
      hidden += text.slice(until, index) + SECRET_MASK;
      until = end;
    } else {
      until = Math.max(until, end);
    }
  });
  return hidden + text.slice(until);
}

describe("hideSecrets", () => {
  test("hides a longer secret that contains a shorter one", () => {
    expect(hideSecrets("old Summer, new Summer2025!", ["Summer", "Summer2025!"])).toBe(
      `old ${SECRET_MASK}, new ${SECRET_MASK}`,
    );
  });

  test("hides overlapping secrets as one and keeps short ones unless asked", () => {
    expect(hideSecrets("xabcdefx", ["abcd", "cdef"])).toBe(`x${SECRET_MASK}x`);
    expect(hideSecrets("pin 123 here", ["123"])).toBe("pin 123 here");
    expect(hideSecrets("pin 123 here", ["123"], 1)).toBe(`pin ${SECRET_MASK} here`);
    expect(hideSecrets("say open sesame", ["open\n  sesame"])).toBe(`say ${SECRET_MASK}`);
  });

  test("matches a plain search for every secret", () => {
    let seed = 7;
    const random = (limit: number) => {
      seed = (seed * 1_103_515_245 + 12_345) % 2_147_483_648;
      return seed % limit;
    };
    const word = (length: number) => Array.from({ length }, () => "ab c"[random(4)]).join("");
    for (let round = 0; round < 3_000; round++) {
      const secrets = Array.from({ length: 1 + random(6) }, () => word(1 + random(6)));
      const text = word(random(40));
      const minimum = random(2) === 0 ? 1 : 4;
      expect(hideSecrets(text, secrets, minimum), JSON.stringify({ text, secrets, minimum })).toBe(
        slowHide(text, secrets, minimum),
      );
    }
  });

  test("stays fast with thousands of secrets", () => {
    const secrets = Array.from({ length: 5_000 }, (_, index) => `pw-${index}-${index * 7919}`);
    const started = performance.now();
    const hide = secretMask(secrets);
    for (let index = 0; index < 10_000; index++) {
      const name = `Button ${index}`;
      expect(hide(`${name} ${secrets[index] ?? "plain"}`)).toBe(
        `${name} ${secrets[index] ? SECRET_MASK : "plain"}`,
      );
    }
    expect(performance.now() - started).toBeLessThan(1_500);
  });

  test("hides the secrets that fit its budget and skips the rest", () => {
    const secrets = Array.from({ length: 30 }, (_, index) => `${index}:`.padEnd(10_000, "x"));
    const hide = secretMask(secrets);
    expect(hide(`a ${secrets[0]} b`)).toBe(`a ${SECRET_MASK} b`);
    expect(hide(secrets[29])).toBe(secrets[29]);
  });
});

import { EventEmitter } from "events";
import { TargetType } from "puppeteer-core";
import { describe, expect, it } from "vitest";
import { BrowserEventType } from "../../../types/enums.js";
import type { BrowserLogger } from "./browser-logger.js";
import { attachCDPEvents } from "./cdp-events.js";
import {
  attachBrowserInteractionEvents,
  BROWSER_INTERACTION_BINDING,
  BROWSER_INTERACTION_WORLD,
} from "./browser-interaction-events.js";
import { BROWSER_INTERACTION_SOURCE } from "./browser-interaction-sanitize.js";
import type { BrowserEventUnion } from "./types.js";

class FakeSession extends EventEmitter {
  calls: Array<{ method: string; params?: any }> = [];
  failRunImmediately = false;

  id() {
    return "fake-session";
  }

  async send(method: string, params?: any) {
    this.calls.push({ method, params });
    if (
      this.failRunImmediately &&
      method === "Page.addScriptToEvaluateOnNewDocument" &&
      params?.runImmediately === true
    ) {
      throw new Error("runImmediately not supported");
    }
    return {};
  }
}

class FakePage extends EventEmitter {
  currentUrl = "about:blank";

  url() {
    return this.currentUrl;
  }
}

function createLogger() {
  const records: BrowserEventUnion[] = [];
  const logger: BrowserLogger = {
    record: (event) => records.push(event),
    resetContext: () => {},
    setContext: () => {},
    getContext: () => ({}),
  };
  return { logger, records };
}

describe("browser interaction CDP attachment", () => {
  it("adds the runtime binding and page script", async () => {
    const session = new FakeSession();
    const page = new FakePage();
    const { logger } = createLogger();

    await attachBrowserInteractionEvents(
      session as any,
      page as any,
      logger,
      TargetType.PAGE,
      "page-1",
    );

    expect(session.calls[0]).toEqual({
      method: "Runtime.addBinding",
      params: {
        name: BROWSER_INTERACTION_BINDING,
        executionContextName: BROWSER_INTERACTION_WORLD,
      },
    });
    expect(session.calls[1]).toMatchObject({
      method: "Page.addScriptToEvaluateOnNewDocument",
      params: {
        worldName: BROWSER_INTERACTION_WORLD,
        runImmediately: true,
      },
    });
    expect(session.calls[1].params.source).toContain(BROWSER_INTERACTION_BINDING);
  });

  it("falls back when runImmediately is not supported", async () => {
    const session = new FakeSession();
    session.failRunImmediately = true;
    const page = new FakePage();
    const { logger } = createLogger();

    await attachBrowserInteractionEvents(
      session as any,
      page as any,
      logger,
      TargetType.PAGE,
      "page-1",
    );

    expect(session.calls).toEqual([
      expect.objectContaining({ method: "Runtime.addBinding" }),
      expect.objectContaining({
        method: "Page.addScriptToEvaluateOnNewDocument",
        params: expect.objectContaining({ runImmediately: true }),
      }),
      expect.objectContaining({
        method: "Page.addScriptToEvaluateOnNewDocument",
        params: expect.not.objectContaining({ runImmediately: true }),
      }),
    ]);
  });

  it("records sanitized binding payloads as browser interactions", async () => {
    const session = new FakeSession();
    const page = new FakePage();
    const { logger, records } = createLogger();

    await attachBrowserInteractionEvents(
      session as any,
      page as any,
      logger,
      TargetType.PAGE,
      "page-1",
    );
    records.length = 0;

    session.emit("Runtime.bindingCalled", {
      name: BROWSER_INTERACTION_BINDING,
      payload: JSON.stringify({
        source: BROWSER_INTERACTION_SOURCE,
        timestamp: "2026-05-22T00:00:00.000Z",
        interaction: {
          action: "click",
          eventType: "click",
          pointer: { x: 1, y: 2, button: 0, clickCount: 1 },
          page: { url: "https://example.com" },
        },
      }),
    });

    expect(records).toHaveLength(1);
    expect(records[0]).toMatchObject({
      type: BrowserEventType.BrowserInteraction,
      timestamp: "2026-05-22T00:00:00.000Z",
      pageId: "page-1",
      interaction: {
        action: "click",
        pointer: { x: 1, y: 2, button: 0, clickCount: 1 },
        page: { url: "https://example.com" },
      },
    });
  });

  it("records only main-frame navigation interactions", async () => {
    const session = new FakeSession();
    const page = new FakePage();
    page.currentUrl = "https://initial.example";
    const { logger, records } = createLogger();

    await attachBrowserInteractionEvents(
      session as any,
      page as any,
      logger,
      TargetType.PAGE,
      "page-1",
    );
    records.length = 0;

    page.emit("framenavigated", {
      parentFrame: () => ({}),
      url: () => "https://iframe.example",
    });
    page.emit("framenavigated", {
      parentFrame: () => null,
      url: () => "https://main.example",
    });

    expect(records).toHaveLength(1);
    expect(records[0]).toMatchObject({
      type: BrowserEventType.BrowserInteraction,
      interaction: {
        action: "navigate",
        navigation: { url: "https://main.example" },
      },
    });
  });

  it("does not duplicate browser interaction binding calls as raw CDP events", () => {
    const session = new FakeSession();
    const { logger, records } = createLogger();

    attachCDPEvents(session as any, logger);
    session.emit("event", {
      method: "Runtime.bindingCalled",
      params: { name: BROWSER_INTERACTION_BINDING },
    });
    session.emit("event", {
      method: "Runtime.bindingCalled",
      params: { name: "otherBinding" },
    });

    expect(records).toHaveLength(1);
    expect(records[0]).toMatchObject({
