import { IProxyServer } from "../utils/proxy.js";
import { SessionService } from "./session.service.js";

/**
 * A proxy whose byte counters settle when it closes, mirroring proxy-chain: a
 * connection is credited on `connectionClosed`, and a long-lived tunnel stays
 * open until the browser goes away.
 */
function createProxyServer() {
  const proxy: IProxyServer & { close: ReturnType<typeof vi.fn> } = {
    url: "http://127.0.0.1:0",
    upstreamProxyUrl: "",
    txBytes: 1_000,
    rxBytes: 2_000,
    listen: vi.fn().mockResolvedValue(undefined),
    close: vi.fn().mockImplementation(async () => {
      Object.assign(proxy, { txBytes: 3_000, rxBytes: 400_000 });
    }),
  };
  return proxy;
}

function createService({ withProxy = false } = {}) {
  const cdpService = {
    getUserAgent: () => "test-agent",
    getDimensions: () => ({ width: 1920, height: 1080 }),
    endSession: vi.fn().mockResolvedValue(undefined),
  };
  const service = new SessionService({
    cdpService: cdpService as never,
    seleniumService: { close: vi.fn() } as never,
    fileService: {} as never,
    logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn() } as never,
  });

  const proxy = withProxy ? createProxyServer() : undefined;
  if (proxy) service.activeSession.proxyServer = proxy;

  return { service, cdpService, proxy };
}

describe("SessionService.endSession proxy accounting", () => {
  it("reports the counters the proxy settles on close", async () => {
    const { service, proxy } = createService({ withProxy: true });

    const released = await service.endSession();

    expect(proxy!.close).toHaveBeenCalledTimes(1);
    expect(proxy!.close).toHaveBeenCalledWith(true);
    expect(released.proxyRxBytes).toBe(400_000);
    expect(released.proxyTxBytes).toBe(3_000);
  });

  it("closes the proxy only after the browser is torn down", async () => {
    const order: string[] = [];
    const { service, cdpService, proxy } = createService({ withProxy: true });
    cdpService.endSession.mockImplementation(async () => {
      order.push("cdp");
    });
    proxy!.close.mockImplementation(async () => {
      order.push("proxy");
    });

    await service.endSession();

    expect(order).toEqual(["cdp", "proxy"]);
  });

  it("leaves the counters at zero when the session had no proxy", async () => {
    const { service } = createService();

    const released = await service.endSession();

    expect(released.proxyRxBytes).toBe(0);
    expect(released.proxyTxBytes).toBe(0);
  });
});

import type { CDPSession } from "puppeteer-core";
import { BrowserEventType } from "../../../types/index.js";
import { BrowserLogger } from "./browser-logger.js";
import { BROWSER_INTERACTION_BINDING } from "./browser-interaction-events.js";

/**
 * Attaches protocol tracing to a CDP session.
 * Logs only protocol commands / notifications so you can diff automation flow between runs.
 */
export function attachCDPEvents(session: CDPSession, logger: BrowserLogger): void {
  const sessionId = session.id?.() ?? "unknown";
  const ts = () => new Date().toISOString();
  const originalSend = session.send.bind(session);
  type Method = Parameters<typeof session.send>[0];

  session.send = async function (method: Method, params?: object) {
    const start = performance.now();

    logger.record({
      type: BrowserEventType.CDPCommand,
      timestamp: ts(),
      cdp: { command: method, params, sessionId },
    });

    try {
      const result = await originalSend(method, params);
      logger.record({
        type: BrowserEventType.CDPCommandResult,
        timestamp: ts(),
        cdp: {
          command: method,
          duration: performance.now() - start,
          sessionId,
          success: true,
        },
      });
      return result;
    } catch (err) {
      logger.record({
        type: BrowserEventType.CDPCommandResult,
        timestamp: ts(),
        cdp: {
          command: method,
          duration: performance.now() - start,
          sessionId,
          success: false,
          error: (err as Error).message,
        },
      });
      throw err;
    }
  } as typeof session.send;

  const ignore = new Set([
    "Runtime.consoleAPICalled",
    "Log.entryAdded",
    // Network events are handled by page-events.ts via typed Request/Response events.
    // Suppress here to avoid duplicate logging.
    "Network.requestWillBeSent",
    "Network.responseReceived",
    "Network.dataReceived",
    "Network.loadingFinished",
    "Network.loadingFailed",
    "Network.requestServedFromCache",
    "Network.requestWillBeSentExtraInfo",
    "Network.responseReceivedExtraInfo",
  ]);
  session.on("event", (event: any) => {
    const { method, params } = event;
    if (ignore.has(method)) return;
    if (method === "Runtime.bindingCalled" && params?.name === BROWSER_INTERACTION_BINDING) return;
    logger.record({
      type: BrowserEventType.CDPEvent,
      timestamp: ts(),
      cdp: { name: method, params },
    });
  });
}

import * as mupdf from "mupdf";
import { describe, expect, it } from "vitest";
import {
  PDF_RENDER_MAX_PIXELS,
  PDF_RENDER_MAX_SIDE,
  pdfRenderScale,
  renderPdfFirstPageAsJpeg,
} from "../pdfToImage.js";

function pdfWithPages(sizes: [number, number][]): Buffer {
  const doc = new mupdf.PDFDocument();
  try {
    for (const [width, height] of sizes) {
      const page = doc.addPage([0, 0, width, height], 0, {}, "0 0 1 rg 10 10 50 50 re f");
      doc.insertPage(-1, page);
    }
    return Buffer.from(doc.saveToBuffer().asUint8Array());
  } finally {
    doc.destroy();
  }
}

function imageSize(jpeg: Buffer): [number, number] {
  const image = new mupdf.Image(jpeg);
  try {
    return [image.getWidth(), image.getHeight()];
  } finally {
    image.destroy();
  }
}

describe("renderPdfFirstPageAsJpeg", () => {
  it("renders the first page as a jpeg at twice its size", () => {
    const jpeg = renderPdfFirstPageAsJpeg(pdfWithPages([[612, 792]]));

    expect([...jpeg.subarray(0, 3)]).toEqual([0xff, 0xd8, 0xff]);
    expect(imageSize(jpeg)).toEqual([1224, 1584]);
  });

  it("ignores pages after the first", () => {
    const jpeg = renderPdfFirstPageAsJpeg(
      pdfWithPages([
        [300, 200],
        [612, 792],
      ]),
    );

    expect(imageSize(jpeg)).toEqual([600, 400]);
  });

  it("keeps a page that declares a huge size within the pixel budget", () => {
    const pdf = pdfWithPages([[14400, 14400]]);

    const [width, height] = imageSize(renderPdfFirstPageAsJpeg(pdf));

    expect(pdf.length).toBeLessThan(1024);
    expect(width * height).toBeLessThanOrEqual(PDF_RENDER_MAX_PIXELS * 1.01);
    expect(width).toBeLessThan(28800);
  });
});

describe("pdfRenderScale", () => {
  it("renders ordinary pages at twice their size", () => {
    expect(pdfRenderScale(612, 792)).toBe(2);
  });

  it("shrinks the scale so a large page stays within the pixel budget", () => {
    const scale = pdfRenderScale(14400, 14400);

    expect(scale).toBeLessThan(2);
    expect(14400 * scale * 14400 * scale).toBeCloseTo(PDF_RENDER_MAX_PIXELS, -3);
  });

  it("keeps a long thin page under the side limit", () => {
    const scale = pdfRenderScale(10, 1_000_000);

    expect(1_000_000 * scale).toBeLessThanOrEqual(PDF_RENDER_MAX_SIDE);
  });

  it("refuses a page with no area", () => {
    expect(() => pdfRenderScale(0, 792)).toThrow("PDF page has no printable area");
    expect(() => pdfRenderScale(612, Number.NaN)).toThrow("PDF page has no printable area");
  });
});

