import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { getDefuddleContent } from "../../readability";
import { CORPUS, loadEntry } from "./corpus";
import { runInvariants } from "./invariants";

const includeHeavy = process.env.SCRAPE_EVAL_HEAVY === "1";

// The pipeline must be fully offline (useAsync:false). Hard-fail if anything
// in the corpus run reaches for the network — that would be a proxy-bypass.
beforeAll(() => {
  vi.stubGlobal(
    "fetch",
    vi.fn(async () => {
      throw new Error("network disabled in eval");
    }),
  );
});
afterAll(() => vi.unstubAllGlobals());

describe("tier1: error invariants hold across the corpus", () => {
  for (const entry of CORPUS) {
    const run = entry.heavy && !includeHeavy ? it.skip : it;

    run(
      `${entry.key} (${entry.category})`,
      async () => {
        const html = loadEntry(entry);
        const result = await getDefuddleContent(html, entry.url);
        const markdown = result.contentMarkdown ?? "";

        const failures = runInvariants({ url: entry.url, html, markdown, result }, "error").filter(
          (r) => !r.pass,
        );

        expect(
          failures,
          `${entry.key}:\n${failures.map((f) => `  ✗ ${f.name} — ${f.detail}`).join("\n")}`,
        ).toEqual([]);
      },
      entry.heavy ? 60000 : 30000,
    );
  }
});

/**
 * Tier 1 eval corpus.
 *
 * The value of the invariant harness scales with how diverse this list is. It is
 * seeded with the existing regression fixtures (tagged by category) and is meant
 * to grow toward a few hundred pages spanning the categories Steel actually sees.
 *
 * To add an entry: capture the page's HTML (use the browser/scrape endpoint for
 * JS-rendered pages), gzip it into ./fixtures (`gzip -9 page.html`), and append a
 * row below. Keep large/slow pages `heavy: true` so they only run under
 * `SCRAPE_EVAL_HEAVY=1` (npm run test:heavy).
 */

import { loadGzHtml, loadRaw } from "../helpers";

export type CorpusEntry = {
  key: string;
  /** filename under ./fixtures; *.gz is gunzipped, anything else read as-is. */
  file: string;
  url: string;
  category: string;
  /** large/slow page — skipped unless SCRAPE_EVAL_HEAVY=1. */
  heavy?: boolean;
};

export const CORPUS: CorpusEntry[] = [
  {
    key: "article",
    file: "article.html.gz",
    url: "https://www.lesswrong.com/posts/WewsByywWNhX9rtwi/current-ais-seem-pretty-misaligned-to-me",
    category: "longform-article",
  },
  {
    key: "wikipedia",
    file: "wikipedia.html.gz",
    url: "https://en.wikipedia.org/wiki/Steel",
    category: "reference",
  },
  {
    key: "arxiv",
    file: "arxiv.html.gz",
    url: "https://arxiv.org/html/1706.03762v7",
    category: "academic-html",
  },
  {
    key: "sec",
    file: "sec.html.gz",
    url: "https://www.sec.gov/",
    category: "gov-listing",
    heavy: true,
  },
  {
    key: "synthetic",
    file: "synthetic.html",
    url: "https://synthetic.test/page",
    category: "synthetic-kitchensink",
  },
  {
    key: "fallback",
    file: "fallback.html",
    url: "https://fallback.test/changelog",
    category: "spa-modal-fallback",
  },
];

export const loadEntry = (entry: CorpusEntry): string =>
  entry.file.endsWith(".gz") ? loadGzHtml(entry.file) : loadRaw(entry.file);

import { describe, expect, it } from "vitest";
import { INVARIANTS, runInvariants, type InvariantContext } from "./invariants";

const ctx = (markdown: string, html = "<html><body></body></html>"): InvariantContext => ({
  url: "https://example.com/page",
  html,
  markdown,
});

const fails = (markdown: string, name: string, html?: string): boolean =>
  runInvariants(ctx(markdown, html)).some((r) => r.name === name && !r.pass);

// A clean, realistic markdown blob that should satisfy every invariant.
const CLEAN = [
  "# Title",
  "",
  "Some body text that is clearly long enough to count as real content, with",
  "more than a handful of words so the contentful check is satisfied here.",
  "",
  "See the [docs](https://example.com/docs) and the [api](https://example.com/api).",
  "",
  "![hero](https://example.com/hero.png)",
  "",
  "```python",
  "print('hi')",
  "```",
].join("\n");

const CONTENTFUL_HTML = `<html><body><article>${"word ".repeat(200)}</article></body></html>`;

describe("invariants: clean markdown passes everything", () => {
  it("produces zero failures on a well-formed document", () => {
    const failures = runInvariants(ctx(CLEAN, CONTENTFUL_HTML)).filter((r) => !r.pass);
    expect(failures.map((f) => `${f.name}: ${f.detail}`)).toEqual([]);
  });
});

describe("invariants: each one catches its failure mode", () => {
  it("no-script-style-leak", () => {
    expect(fails("text <script>alert(1)</script> more", "no-script-style-leak")).toBe(true);
    expect(fails("text <style>.a{}</style>", "no-script-style-leak")).toBe(true);
  });

  it("no-relative-links", () => {
    expect(fails("[home](/home)", "no-relative-links")).toBe(true);
    expect(fails("[up](../sibling)", "no-relative-links")).toBe(true);
    expect(fails("[here](./local)", "no-relative-links")).toBe(true);
    // protocol-relative and absolute must NOT trip it
    expect(fails("[cdn](//cdn.example.com/x)", "no-relative-links")).toBe(false);
    expect(fails("[abs](https://example.com/x)", "no-relative-links")).toBe(false);
  });

  it("no-mangled-links", () => {
    expect(fails('[x](https://e.com/a"title)', "no-mangled-links")).toBe(true);
  });

  it("non-empty-when-contentful", () => {
    expect(fails("", "non-empty-when-contentful", CONTENTFUL_HTML)).toBe(true);
    // an empty page must NOT trip it (nothing to extract)
    expect(fails("", "non-empty-when-contentful", "<html><body></body></html>")).toBe(false);
  });

  it("no-secret-leak", () => {
    expect(fails(`token sk-${"a1B2c3D4e5".repeat(3)} here`, "no-secret-leak")).toBe(true);
    expect(fails("[REDACTED] is a key", "no-secret-leak")).toBe(true);
    expect(fails("-----BEGIN PRIVATE KEY-----", "no-secret-leak")).toBe(true);
    expect(fails("the word sketch is fine", "no-secret-leak")).toBe(false);
  });

  it("no-leaked-chrome-tags (warn)", () => {
    expect(fails("<nav>menu</nav>", "no-leaked-chrome-tags")).toBe(true);
    expect(fails("<iframe src=x></iframe>", "no-leaked-chrome-tags")).toBe(true);
  });

  it("no-empty-image-src (warn)", () => {
    expect(fails("![lost]()", "no-empty-image-src")).toBe(true);
    expect(fails("![ok](https://e.com/i.png)", "no-empty-image-src")).toBe(false);
  });

  it("no-empty-or-fragment-links (warn)", () => {
    expect(fails("see [toc](#section)", "no-empty-or-fragment-links")).toBe(true);
    expect(fails("a [x]() b", "no-empty-or-fragment-links")).toBe(true);
  });

  it("balanced-code-fences (warn)", () => {
    expect(fails("```python\nprint(1)", "balanced-code-fences")).toBe(true);
    expect(fails("```python\nprint(1)\n```", "balanced-code-fences")).toBe(false);
  });

  it("no-html-comments (warn)", () => {
    expect(fails("text <!-- tracking --> text", "no-html-comments")).toBe(true);
  });

  it("size-ratio-sane (warn)", () => {
    const tinyHtml = `<html><body>${"w ".repeat(60)}</body></html>`;
    const bloated = "dup ".repeat(300);
    expect(fails(bloated, "size-ratio-sane", tinyHtml)).toBe(true);
  });
});

describe("invariants: severity split is wired", () => {
  it("error subset is a strict subset of all invariants", () => {
    const errors = runInvariants(ctx(CLEAN, CONTENTFUL_HTML), "error");
    expect(errors.length).toBeGreaterThan(0);
    expect(errors.length).toBeLessThan(INVARIANTS.length);
    expect(errors.every((r) => r.severity === "error")).toBe(true);
  });
});

# Plugin Development Guide

This guide walks you through developing custom plugins for Steel Browser's extensible architecture.

## 🚀 Quick Start

### Creating Your First Plugin

```typescript
import { BasePlugin, PluginOptions } from '@steel-browser/api/cdp-plugin';
import { Browser, Page } from 'puppeteer-core';

export class HelloWorldPlugin extends BasePlugin {
  constructor(options: PluginOptions) {
    super({ name: 'hello-world', ...options });
  }

  async onBrowserLaunch(browser: Browser): Promise<void> {
    console.log('Hello from the browser launch event!');
  }

  async onPageCreated(page: Page): Promise<void> {
    console.log(`New page created: ${page.url()}`);
  }
}

// Usage
const plugin = new HelloWorldPlugin({});
cdpService.registerPlugin(plugin);
```

## 🏗️ Plugin Architecture

### Base Plugin Class

All plugins extend the `BasePlugin` abstract class:

```typescript
abstract class BasePlugin {
  public name: string;
  protected options: PluginOptions;
  protected cdpService: CDPService | null;

  constructor(options: PluginOptions);
  public setService(service: CDPService): void;

  // Lifecycle hooks (all optional)
  public async onBrowserLaunch(browser: Browser): Promise<void> {}
  public async onPageCreated(page: Page): Promise<void> {}
  public async onPageNavigate(page: Page): Promise<void> {}
  public async onPageUnload(page: Page): Promise<void> {}
  public async onBrowserClose(browser: Browser): Promise<void> {}
  public async onBeforePageClose(page: Page): Promise<void> {}
  public async onShutdown(): Promise<void> {}
}
```

### Plugin Options

```typescript
interface PluginOptions {
  name: string;
  [key: string]: any; // Additional plugin-specific options
}
```

## 🔄 Lifecycle Events

### Event Order

```
1. onBrowserLaunch    - Browser process starts
2. onPageCreated      - New page/tab created
3. onPageNavigate     - Page navigates to URL
4. onPageUnload       - Page unloads/navigates away
5. onBeforePageClose  - Before page closes
6. onBrowserClose     - Browser process closes
7. onShutdown         - Plugin cleanup
```

### Event Details

#### onBrowserLaunch(browser: Browser)
- Called when the browser process starts
- Use for browser-level configuration
- Access to the Browser instance

#### onPageCreated(page: Page)
- Called when a new page/tab is created
- Perfect for page-level setup (request interception, etc.)
- Access to the Page instance

#### onPageNavigate(page: Page)
- Called before page navigation
- Use for URL-based logic or navigation tracking

#### onPageUnload(page: Page)
- Called when page unloads or navigates away
- Cleanup page-specific resources

#### onBeforePageClose(page: Page)
- Called before a page closes
- Last chance for page cleanup

#### onBrowserClose(browser: Browser)
- Called when browser process closes
- Browser-level cleanup

#### onShutdown()
- Called during plugin shutdown
- Final cleanup opportunity

## 📝 Plugin Examples

### 1. Request Logger Plugin

```typescript
export class RequestLoggerPlugin extends BasePlugin {
  private logFile: string;

  constructor(options: PluginOptions & { logFile?: string }) {
    super({ name: 'request-logger', ...options });
    this.logFile = options.logFile || 'requests.log';
  }

  async onPageCreated(page: Page): Promise<void> {
    await page.setRequestInterception(true);

    page.on('request', (request) => {
      const logEntry = {
        timestamp: new Date().toISOString(),
        method: request.method(),
        url: request.url(),
        headers: request.headers()
      };

      // Log to file or console
      console.log('Request:', logEntry);
      request.continue();
    });
  }
}
```

### 2. Ad Blocker Plugin

```typescript
export class AdBlockerPlugin extends BasePlugin {
  private blockedDomains: Set<string>;
  private blockedCount: number = 0;

  constructor(options: PluginOptions & { blockedDomains?: string[] }) {
    super({ name: 'ad-blocker', ...options });
    this.blockedDomains = new Set(options.blockedDomains || [
      'doubleclick.net',
      'googleadservices.com',
      'googlesyndication.com'
    ]);
  }

  async onPageCreated(page: Page): Promise<void> {
    await page.setRequestInterception(true);

    page.on('request', (request) => {
      const url = new URL(request.url());

      if (this.blockedDomains.has(url.hostname)) {
        this.blockedCount++;
        console.log(`Blocked ad request: ${url.hostname}`);
        request.abort();
      } else {
        request.continue();
      }
    });
  }

  async onShutdown(): Promise<void> {
    console.log(`Ad Blocker: Blocked ${this.blockedCount} requests`);
  }
}
```

### 3. Screenshot Plugin

```typescript
export class ScreenshotPlugin extends BasePlugin {
  private screenshotDir: string;

  constructor(options: PluginOptions & { screenshotDir?: string }) {
    super({ name: 'screenshot', ...options });
    this.screenshotDir = options.screenshotDir || './screenshots';
  }

  async onPageNavigate(page: Page): Promise<void> {
    // Take screenshot after navigation
    setTimeout(async () => {
      try {
        const url = new URL(page.url());
        const filename = `${url.hostname}-${Date.now()}.png`;
        const filepath = path.join(this.screenshotDir, filename);

        await page.screenshot({ path: filepath, fullPage: true });
        console.log(`Screenshot saved: ${filepath}`);
      } catch (error) {
        console.error('Screenshot failed:', error);
      }
    }, 2000);
  }
}
```

### 4. Performance Monitor Plugin

```typescript
export class PerformancePlugin extends BasePlugin {
  private metrics: Map<string, any> = new Map();

  constructor(options: PluginOptions) {
    super({ name: 'performance-monitor', ...options });
  }

  async onPageCreated(page: Page): Promise<void> {
    // Enable performance monitoring
    await page.coverage.startJSCoverage();
    await page.coverage.startCSSCoverage();

    page.on('load', async () => {
      const performanceMetrics = await page.evaluate(() => {
        const perfData = performance.getEntriesByType('navigation')[0];
        return {
          domContentLoaded: perfData.domContentLoadedEventEnd - perfData.domContentLoadedEventStart,
          loadComplete: perfData.loadEventEnd - perfData.loadEventStart,
          firstPaint: performance.getEntriesByType('paint')[0]?.startTime || 0
        };
      });

      this.metrics.set(page.url(), performanceMetrics);
      console.log(`Performance metrics for ${page.url()}:`, performanceMetrics);
    });
  }

  async onShutdown(): Promise<void> {
    console.log('Performance Summary:', Object.fromEntries(this.metrics));
  }
}
```

